/** Make a new independent character instance. Pass the host's THREE module. */
export function createMan(THREE) {
  if (!THREE || typeof THREE.ObjectLoader !== 'function') {
    throw new TypeError('createMan(THREE) requires the Three.js namespace.');
  }
  const root = new THREE.ObjectLoader().parse(characterData.scene);
  root.traverse(node => {
    const state = characterData.precision.nodes[node.uuid];
    if (state) {
      node.position.fromArray(state.position);
      node.quaternion.fromArray(state.quaternion);
      node.scale.fromArray(state.scale);
      node.matrixAutoUpdate = state.matrixAutoUpdate;
      node.matrix.fromArray(state.matrix);
      node.matrixWorldNeedsUpdate = true;
    }
    const materials = node.material ? (Array.isArray(node.material) ? node.material : [node.material]) : [];
    for (const material of materials) {
      const values = characterData.precision.materials[material.uuid];
      if (values) for (const [key, components] of Object.entries(values)) {
        if (material[key] && typeof material[key].fromArray === 'function') material[key].fromArray(components);
      }
    }
    const binding = characterData.precision.bindings[node.uuid];
    if (binding && node.isSkinnedMesh) {
      node.bindMode = binding.bindMode;
      node.bindMatrix.fromArray(binding.bindMatrix);
      node.bindMatrixInverse.fromArray(binding.bindMatrixInverse);
    }
  });
  root.updateMatrixWorld(true);
  return root;
}

export const metadata = characterData.metadata;
